class RangeTracker {
  private iv: number[][] = []; // sorted, disjoint, non-touching [start, end)

  addRange(left: number, right: number): void {
    const out: number[][] = [];
    let i = 0;
    while (i < this.iv.length && this.iv[i][1] < left) out.push(this.iv[i++]);
    while (i < this.iv.length && this.iv[i][0] <= right) {
      left = Math.min(left, this.iv[i][0]);
      right = Math.max(right, this.iv[i][1]);
      i++;
    }
    out.push([left, right]);
    while (i < this.iv.length) out.push(this.iv[i++]);
    this.iv = out;
  }

  queryRange(left: number, right: number): boolean {
    let lo = 0, hi = this.iv.length - 1, found = -1; // last interval starting at or before left
    while (lo <= hi) {
      const mid = (lo + hi) >> 1;
      if (this.iv[mid][0] <= left) { found = mid; lo = mid + 1; } else hi = mid - 1;
    }
    return found >= 0 && this.iv[found][1] >= right;
  }

  removeRange(left: number, right: number): void {
    const out: number[][] = [];
    for (const [s, e] of this.iv) {
      if (e <= left || s >= right) { out.push([s, e]); continue; }
      if (s < left) out.push([s, left]);
      if (e > right) out.push([right, e]);
    }
    this.iv = out;
  }
}

