class RangeTracker {
  private b: number[] = []; // [s0, e0, s1, e1, ...], covered = [s_i, e_i)

  // first index whose boundary is >= x (strict = false) or > x (strict = true)
  private find(x: number, strict: boolean): number {
    let lo = 0, hi = this.b.length;
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (strict ? this.b[mid] <= x : this.b[mid] < x) lo = mid + 1; else hi = mid;
    }
    return lo;
  }

  addRange(left: number, right: number): void {
    const i = this.find(left, false), j = this.find(right, true);
    const keep: number[] = [];
    if (i % 2 === 0) keep.push(left);  // left is outside every range: it starts a new one
    if (j % 2 === 0) keep.push(right); // right is outside every range: it ends the merged one
    this.b.splice(i, j - i, ...keep);
  }

  queryRange(left: number, right: number): boolean {
    const i = this.find(left, true), j = this.find(right, false);
    return i === j && i % 2 === 1;
  }

  removeRange(left: number, right: number): void {
    const i = this.find(left, false), j = this.find(right, true);
    const keep: number[] = [];
    if (i % 2 === 1) keep.push(left);  // left was inside a range: that range now ends at left
    if (j % 2 === 1) keep.push(right); // right was inside a range: that range now starts at right
    this.b.splice(i, j - i, ...keep);
  }
}

